std::vector<std::pair<Point3d, Vector3d>> rays;
    rays.reserve(numberOfChecks);

    // Generate pseudo-random directions using a simple LCG
    std::linear_congruential_engine<std::uint_fast32_t, 1664525, 1013904223, 0> rng(std::hash<double>{}(p.x() + p.y() + p.z()));
    std::uniform_real_distribution<double> dist(-1.0, 1.0);

    for (int i = 0; i < numberOfChecks; ++i) {
        Vector3d dir;
        do {
            dir = Vector3d(dist(rng), dist(rng), dist(rng));
        } while (dir.squared_length() < std::numeric_limits<double>::epsilon());
        dir = dir / std::sqrt(dir.squared_length());
        rays.emplace_back(p, dir);
    }

    int intersections = 0;
    for (const auto& ray : rays) {
        const auto& [origin, direction] = ray;
        Ray3d query(origin, direction);
        intersections += tree.number_of_intersected_primitives(query);
    }

    // Point is inside if odd number of intersections
    return (intersections % 2) != 0;
    // END_CODE

